// SPDX-License-Identifier: Apache-2.0
package jdk.internal.mindex;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import java.util.function.LongPredicate;

/**
 * TQ (Trigram Query): conservative boolean queries over UTF-16 trigrams.
 *
 * <p>JDK-owned adaptation of Synexia MIndexRegexTrigramQuery. No Synexia module is
 * required at build time or runtime. See m3/tooling/tq for exact provenance.</p>
 *
 * <p>The query is a necessary condition only: a false result proves that a regex cannot match,
 * while a true result always requires the authoritative regex verifier. This is deliberately the
 * same candidate-only contract used by the rest of the MIndex search geometry.</p>
 */
public final class M3TQ {
  public enum Op {
    ALL,
    NONE,
    AND,
    OR
  }

  private static final M3TQ ALL =
      new M3TQ(Op.ALL, new long[0], List.of());
  private static final M3TQ NONE =
      new M3TQ(Op.NONE, new long[0], List.of());

  private final Op op;
  private final long[] trigrams;
  private final List<M3TQ> subqueries;

  private M3TQ(
      Op op, long[] trigrams, List<M3TQ> subqueries) {
    this.op = Objects.requireNonNull(op, "op");
    this.trigrams = Objects.requireNonNull(trigrams, "trigrams").clone();
    Arrays.sort(this.trigrams);
    this.subqueries = List.copyOf(Objects.requireNonNull(subqueries, "subqueries"));
  }

  public static M3TQ all() {
    return ALL;
  }

  public static M3TQ none() {
    return NONE;
  }

  public static M3TQ fromExact(List<String> exact) {
    Objects.requireNonNull(exact, "exact");
    if (exact.isEmpty()) return NONE;

    ArrayList<M3TQ> alternatives = new ArrayList<>(exact.size());
    for (String value : exact) {
      String checked = Objects.requireNonNull(value, "exact value");
      if (checked.length() < 3) {
        // One legal branch can match without any trigram, so no trigram is globally required.
        return ALL;
      }
      long[] grams = uniqueTrigrams(checked);
      alternatives.add(new M3TQ(Op.AND, grams, List.of()));
    }
    return combine(Op.OR, alternatives);
  }

  public static M3TQ and(List<M3TQ> terms) {
    return combine(Op.AND, terms);
  }

  public static M3TQ or(List<M3TQ> terms) {
    return combine(Op.OR, terms);
  }

  private static M3TQ combine(
      Op op, List<M3TQ> input) {
    if (op != Op.AND && op != Op.OR) throw new IllegalArgumentException("combine op");
    Objects.requireNonNull(input, "input");

    ArrayList<M3TQ> flat = new ArrayList<>();
    ArrayList<Long> grams = new ArrayList<>();
    for (M3TQ term : input) {
      M3TQ checked = Objects.requireNonNull(term, "term");
      if (op == Op.AND) {
        if (checked.op == Op.NONE) return NONE;
        if (checked.op == Op.ALL) continue;
      } else {
        if (checked.op == Op.ALL) return ALL;
        if (checked.op == Op.NONE) continue;
      }

      if (checked.op == op) {
        for (long gram : checked.trigrams) grams.add(gram);
        flat.addAll(checked.subqueries);
      } else if (checked.subqueries.isEmpty() && checked.trigrams.length == 1) {
        grams.add(checked.trigrams[0]);
      } else {
        flat.add(checked);
      }
    }

    if (grams.isEmpty() && flat.isEmpty()) return op == Op.AND ? ALL : NONE;
    if (grams.isEmpty() && flat.size() == 1) return flat.getFirst();

    long[] gramArray = new long[grams.size()];
    for (int i = 0; i < gramArray.length; i++) gramArray[i] = grams.get(i);
    if (gramArray.length > 1) {
      Arrays.sort(gramArray);
      int unique = 1;
      for (int i = 1; i < gramArray.length; i++) {
        if (gramArray[i] != gramArray[unique - 1]) gramArray[unique++] = gramArray[i];
      }
      gramArray = Arrays.copyOf(gramArray, unique);
    }
    return new M3TQ(op, gramArray, flat);
  }

  public Op op() {
    return op;
  }

  public long[] trigrams() {
    return trigrams.clone();
  }

  public List<M3TQ> subqueries() {
    return subqueries;
  }

  long[] trigramsForReadOnlyKernel() {
    return trigrams;
  }

  List<M3TQ> subqueriesForReadOnlyKernel() {
    return subqueries;
  }

  public boolean hasConstraints() {
    return op != Op.ALL;
  }

  public int termCount() {
    int count = trigrams.length;
    for (M3TQ subquery : subqueries) {
      count = Math.addExact(count, subquery.termCount());
    }
    return count;
  }

  /** Evaluate only the conservative trigram condition. */
  public boolean test(LongPredicate containsTrigram) {
    Objects.requireNonNull(containsTrigram, "containsTrigram");
    return switch (op) {
      case ALL -> true;
      case NONE -> false;
      case AND -> {
        for (long gram : trigrams) {
          if (!containsTrigram.test(gram)) yield false;
        }
        for (M3TQ subquery : subqueries) {
          if (!subquery.test(containsTrigram)) yield false;
        }
        yield true;
      }
      case OR -> {
        for (long gram : trigrams) {
          if (containsTrigram.test(gram)) yield true;
        }
        for (M3TQ subquery : subqueries) {
          if (subquery.test(containsTrigram)) yield true;
        }
        yield false;
      }
    };
  }

  /**
   * Precompute exact UTF-16 trigram membership without retaining or materializing the input.
   *
   * <p>The caller must keep the input stable throughout this bounded scan and associate the
   * result with that exact immutable value/range. This is not a persistent resolver identity.
   * Preparation reads each code unit once, sorts at most {@code length - 2} keys and retains
   * only unique keys and two boundary units at each end. Budgets count UTF-16 units, not bytes.
   *
   * @param value stable text, including an indexed or sliced CharSequence
   * @param maxUtf16Units nonnegative maximum length admitted before any character read
   * @return caller-owned immutable membership facts
   * @throws IllegalArgumentException if the length or budget is invalid or exceeds the budget
   */
  public static Facts precompute(CharSequence value, int maxUtf16Units) {
    Objects.requireNonNull(value, "value");
    int length = value.length();
    requireFactBudget(length, maxUtf16Units);
    return scanFacts(value, 0, length);
  }

  /**
   * Prepare facts for a half-open UTF-16 range without slicing or materializing the source.
   *
   * <p>Null, range and range-length budget checks precede character reads and key allocation.
   * Each admitted unit is read once; units outside the range are never read. The caller must
   * keep the source stable during preparation and bind the result to that exact source/range.
   * The budget applies to the range, not the backing sequence's length or total resident bytes.
   * These facts describe only the isolated range: transparent regex lookarounds may observe
   * outside it, so constraints derived from such context require separately justified scope.
   *
   * @param value stable indexed, joined, sliced or ordinary character sequence
   * @param from inclusive UTF-16 start
   * @param to exclusive UTF-16 end
   * @param maxUtf16Units nonnegative maximum range length
   * @return immutable membership facts for the isolated range
   * @throws NullPointerException if value is null
   * @throws IndexOutOfBoundsException if the range is invalid
   * @throws IllegalArgumentException if the budget is negative or smaller than the range
   */
  public static Facts precompute(CharSequence value, int from, int to, int maxUtf16Units) {
    Objects.requireNonNull(value, "value");
    Objects.checkFromToIndex(from, to, value.length());
    int length = to - from;
    requireFactBudget(length, maxUtf16Units);
    return scanFacts(value, from, length);
  }

  /**
   * Prepare exact range facts directly from an existing canonical JDK String backing.
   *
   * <p>No materialization, UTF-16 view export, or second retained payload is created.
   * The temporary reader is discarded after preparation. The backing must remain open
   * and immutable throughout the scan. The caller binds reuse to the exact owner,
   * generation, id and range; equal numeric ids in different owners are not identity.
   * This overload does not install a global cache or change Pattern/Matcher dispatch.
   *
   * @param backing existing immutable backing owner
   * @param id owner-local text coordinate, never a process pointer
   * @param from inclusive UTF-16 start
   * @param to exclusive UTF-16 end
   * @param maxUtf16Units maximum admitted range length
   * @return caller-owned immutable facts with no retained backing reference
   */
  public static Facts precompute(M3StringBacking backing, long id,
      int from, int to, int maxUtf16Units) {
    Objects.requireNonNull(backing, "backing");
    return precompute(new CharSequence() {
      @Override public int length() { return backing.length(id); }
      @Override public char charAt(int index) { return backing.charAt(id, index); }
      @Override public CharSequence subSequence(int start, int end) {
        throw new UnsupportedOperationException("range reader does not materialize slices");
      }
    }, from, to, maxUtf16Units);
  }

  private static Facts scanFacts(CharSequence value, int from, int length) {
    long[] keys = new long[Math.max(0, length - 2)];
    long window = 0L;
    int prefix = 0;
    for (int index = 0; index < length; index++) {
      char unit = value.charAt(from + index);
      if (index < 2) prefix = (prefix << 16) | unit;
      window = ((window << 16) | unit) & 0xffffffffffffL;
      if (index >= 2) keys[index - 2] = window;
    }
    Arrays.sort(keys);
    return new Facts(length, prefix, (int) window, compactFactKeys(keys));
  }

  /**
   * Evaluate only the existing necessary-condition query against prepared membership facts.
   * A true result is not an exact regex match, position, count or equality proof.
   */
  public boolean testPrecomputed(Facts facts) {
    return test(Objects.requireNonNull(facts, "facts"));
  }

  /**
   * Immutable derived search metadata; never a second canonical spelling store.
   *
   * <p>Composition merges exact key sets and at most two seam keys. It does not read either
   * original payload. Sorted membership discards multiplicity and order: these facts cannot
   * establish a match or recover arbitrary slices. Array exports are defensive copies.
   */
  public static final class Facts implements LongPredicate {
    private final int utf16Length;
    private final int prefix;
    private final int suffix;
    private final long[] keys;

    private Facts(int utf16Length, int prefix, int suffix, long[] ownedKeys) {
      this.utf16Length = utf16Length;
      this.prefix = prefix;
      this.suffix = suffix;
      this.keys = ownedKeys;
    }

    /** Number of UTF-16 units in the exact value represented by these facts. */
    public int utf16Length() {
      return utf16Length;
    }

    /** Number of distinct packed 48-bit keys, not the number of occurrences. */
    public int keyCount() {
      return keys.length;
    }

    /** Sorted unique membership keys; changing the export cannot change these facts. */
    public long[] keys() {
      return keys.clone();
    }

    /** Exact membership in this UTF-16 trigram set; not a regex acceptance predicate. */
    @Override
    public boolean test(long key) {
      return Arrays.binarySearch(keys, key) >= 0;
    }

    /**
     * Returns true when every exact trigram in {@code required} is present in this fact set.
     *
     * <p>This is still only a substring/regex necessary condition: membership discards ordering
     * and multiplicity, so true always requires exact verification.</p>
     */
    public boolean containsAll(Facts required) {
      Objects.requireNonNull(required, "required");
      int source = 0;
      int needle = 0;
      while (source < keys.length && needle < required.keys.length) {
        long left = keys[source];
        long right = required.keys[needle];
        if (left < right) source++;
        else if (left == right) {
          source++;
          needle++;
        } else {
          return false;
        }
      }
      return needle == required.keys.length;
    }

    /**
     * Prepare facts for the ordered concatenation using metadata only.
     *
     * <p>With k retained keys this uses O(k) merge work and O(k) temporary/output space.
     * The budget is checked before allocation, including for empty identities. No global
     * cache or all-pairs precomputation is performed. Callers own retention and reuse.
     *
     * @param right facts for the immediately following value
     * @param maxUtf16Units nonnegative maximum combined length
     * @return facts observationally equal to preparing the concatenated text
     * @throws ArithmeticException if combined length exceeds the Java int coordinate domain
     * @throws IllegalArgumentException if the budget is invalid or exceeded
     */
    public Facts concat(Facts right, int maxUtf16Units) {
      Objects.requireNonNull(right, "right");
      int length = Math.addExact(utf16Length, right.utf16Length);
      requireFactBudget(length, maxUtf16Units);
      if (utf16Length == 0) return right;
      if (right.utf16Length == 0) return this;
      int nextPrefix = utf16Length >= 2 ? prefix : (suffix << 16) | right.first();
      int nextSuffix = right.utf16Length >= 2
          ? right.suffix : ((int) (char) suffix << 16) | right.suffix;
      long[] seam = seamKeys(right);
      return new Facts(length, nextPrefix, nextSuffix, mergeFactKeys(keys, right.keys, seam));
    }

    private char first() {
      return (char) (utf16Length == 1 ? prefix : prefix >>> 16);
    }

    private long[] seamKeys(Facts right) {
      int count = (utf16Length >= 2 ? 1 : 0) + (right.utf16Length >= 2 ? 1 : 0);
      long[] seam = new long[count];
      int index = 0;
      if (utf16Length >= 2) {
        seam[index++] = trigram((char) (suffix >>> 16), (char) suffix, right.first());
      }
      if (right.utf16Length >= 2) {
        seam[index] = trigram((char) suffix, right.first(), (char) right.prefix);
      }
      Arrays.sort(seam);
      return seam;
    }
  }

  private static void requireFactBudget(int length, int budget) {
    if (length < 0 || budget < 0 || length > budget) {
      throw new IllegalArgumentException("UTF-16 precompute budget exceeded or invalid");
    }
  }

  private static long[] compactFactKeys(long[] keys) {
    if (keys.length < 2) return keys;
    int count = 1;
    for (int index = 1; index < keys.length; index++) {
      if (keys[index] != keys[count - 1]) keys[count++] = keys[index];
    }
    return count == keys.length ? keys : Arrays.copyOf(keys, count);
  }

  private static long[] mergeFactKeys(long[] left, long[] right, long[] seam) {
    int capacity = Math.addExact(Math.addExact(left.length, right.length), seam.length);
    long[] merged = new long[capacity];
    int a = 0;
    int b = 0;
    int c = 0;
    int count = 0;
    while (a < left.length || b < right.length || c < seam.length) {
      long key = Math.min(a < left.length ? left[a] : Long.MAX_VALUE,
          Math.min(b < right.length ? right[b] : Long.MAX_VALUE,
              c < seam.length ? seam[c] : Long.MAX_VALUE));
      if (a < left.length && left[a] == key) a++;
      if (b < right.length && right[b] == key) b++;
      if (c < seam.length && seam[c] == key) c++;
      if (count == 0 || merged[count - 1] != key) merged[count++] = key;
    }
    return count == capacity ? merged : Arrays.copyOf(merged, count);
  }

  /** Packs three UTF-16 units into one unsigned 48-bit key. */
  public static long trigram(char first, char second, char third) {
    return ((long) first << 32) | ((long) second << 16) | third;
  }

  static long[] uniqueTrigrams(CharSequence value) {
    Objects.requireNonNull(value, "value");
    if (value.length() < 3) return new long[0];
    long[] keys = new long[value.length() - 2];
    for (int i = 0; i < keys.length; i++) {
      keys[i] = trigram(value.charAt(i), value.charAt(i + 1), value.charAt(i + 2));
    }
    Arrays.sort(keys);
    int unique = 1;
    for (int i = 1; i < keys.length; i++) {
      if (keys[i] != keys[unique - 1]) keys[unique++] = keys[i];
    }
    return Arrays.copyOf(keys, unique);
  }

  @Override
  public String toString() {
    return switch (op) {
      case ALL -> "ALL";
      case NONE -> "NONE";
      case AND, OR -> render();
    };
  }

  private String render() {
    String separator = op == Op.AND ? " & " : " | ";
    ArrayList<String> terms = new ArrayList<>(trigrams.length + subqueries.size());
    for (long gram : trigrams) terms.add(quote(gram));
    for (M3TQ subquery : subqueries) {
      terms.add("(" + subquery + ")");
    }
    return String.join(separator, terms);
  }

  private static String quote(long gram) {
    char first = (char) (gram >>> 32);
    char second = (char) (gram >>> 16);
    char third = (char) gram;
    return "'" + new String(new char[] {first, second, third}) + "'";
  }
}

// SPDX-License-Identifier: Apache-2.0
/*
 * @test
 * @summary Verify TQ range facts, canonical backing reuse and required JNI parity
 * @modules java.base/jdk.internal.mindex
 * @build M3MappedStringBackingTest
 * @run main/native M3TQTest
 */

import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.TreeSet;
import java.util.regex.Pattern;
import jdk.internal.mindex.M3TQ;
import jdk.internal.mindex.M3MappedStringBacking;
import jdk.internal.mindex.M3StringBacking;

public class M3TQTest {
    private static long checks;
    private static long ranges;
    private static long compositions;
    private static long nativeCalls;
    private static long coldReads;
    private static long mappedRanges;
    private static long containmentPairs;
    private static final List<String> LITERALS = List.of("", "a", "aba", "bab", "abc",
            "\u0000\u0100\uD800", "\uD800\uDC00a", "\\Qx\\E");
    private static final List<M3TQ> QUERIES = LITERALS.stream()
            .map(value -> M3TQ.fromExact(List.of(value))).toList();
    private static final List<Pattern> PATTERNS = LITERALS.stream()
            .map(value -> Pattern.compile(Pattern.quote(value))).toList();
    private static native long[] nativeKeys(char[] text);
    private static native long[] nativeRangeKeys(char[] text, int from, int to, int budget);

    public static void main(String[] args) throws Exception {
        System.loadLibrary("M3TQTest");
        check(M3TQ.class.getModule().getName().equals("java.base"), "actual java.base owner");
        check(M3TQ.class.getClassLoader() == null, "bootstrap-loaded kernel");
        List<String> corpus = new ArrayList<>();
        enumerate(corpus, "", 3);
        corpus.addAll(List.of("ababa", "abcabc", "\uFFFF\uFFFF\uFFFF", "A\uD800x\uD83D\uDE00\uDC00Z",
                "class C{}", "a.*b", "\\u0061", "\"null\"", "a\nb\rc\u0000", "abababab"));
        for (String text : corpus) {
            char[] units = text.toCharArray(), original = units.clone();
            equal(oracle(text, 0, text.length()), nativeKeys(units), "native whole");
            nativeCalls++;
            for (int from = 0; from <= text.length(); from++) {
                for (int to = from; to <= text.length(); to++) {
                    range(text, units, from, to);
                }
            }
            check(Arrays.equals(original, units), "native preserves input");
        }
        containment(corpus);
        queryAlgebra();
        refusals();
        mapped();
        System.out.printf("TQ checks=%d strings=%d ranges=%d compositions=%d nativeCalls=%d coldReads=%d mappedRanges=%d containmentPairs=%d warmPayloadReads=0%n",
                checks, corpus.size(), ranges, compositions, nativeCalls, coldReads, mappedRanges, containmentPairs);
    }

    private static void enumerate(List<String> result, String prefix, int remaining) {
        result.add(prefix);
        if (remaining == 0) return;
        for (char unit : new char[]{'a', 'b', '\u0000', '\u00FF', '\u0100', '\uD800', '\uDC00'}) {
            enumerate(result, prefix + unit, remaining - 1);
        }
    }

    private static void range(String text, char[] units, int from, int to) {
        int length = to - from;
        long[] expected = oracle(text, from, to);
        Fence reader = new Fence(text, from, to);
        M3TQ.Facts facts = M3TQ.precompute(reader, from, to, length);
        check(reader.reads == length, "one cold read per admitted unit");
        coldReads += reader.reads;
        reader.sealed = true;
        equal(expected, facts.keys(), "range facts");
        equal(expected, nativeRangeKeys(units, from, to, length), "native range");
        nativeCalls++;
        check(facts.utf16Length() == length && facts.keyCount() == expected.length, "fact dimensions");
        long[] exposed = facts.keys();
        if (exposed.length != 0) exposed[0] = -1;
        equal(expected, facts.keys(), "defensive export");
        check(!facts.test(-1) && !facts.test(1L << 48), "outside packed-key domain");
        for (long key : expected) check(facts.test(key), "exact membership");
        for (int split = from; split <= to; split++) {
            Fence leftReader = new Fence(text, from, split), rightReader = new Fence(text, split, to);
            var left = M3TQ.precompute(leftReader, from, split, length);
            var right = M3TQ.precompute(rightReader, split, to, length);
            check(leftReader.reads + rightReader.reads == length, "partition cold reads");
            leftReader.sealed = rightReader.sealed = true;
            equal(expected, left.concat(right, length).keys(), "seam composition");
            check(left.concat(right, length).utf16Length() == length, "composed length");
            compositions++;
        }
        for (int p = 0; p < QUERIES.size(); p++) {
            boolean guard = QUERIES.get(p).testPrecomputed(facts);
            boolean match = PATTERNS.get(p).matcher(text).region(from, to).find();
            check(!match || guard, "literal guard cannot reject a true region match");
        }
        ranges++;
    }

    private static void containment(List<String> corpus) {
        var values = new ArrayList<>(corpus);
        values.addAll(List.of("abc-bcd", "abcd", "abcabc", "abcabcabc", "bcabca",
                "\u0000\u0100\uFFFF", "\uD800\uDC00\uD800\uDC00"));
        var random = new java.util.Random(0x73a51L);
        for (int i = 0; i < 32; i++) {
            var value = new StringBuilder();
            for (int j = 0; j < 32; j++) value.append((char) random.nextInt(65536));
            values.add(value.toString());
        }
        var facts = new ArrayList<M3TQ.Facts>();
        var keys = new ArrayList<TreeSet<Long>>();
        var readers = new ArrayList<Fence>();
        for (String value : values) {
            Fence reader = new Fence(value, 0, value.length());
            facts.add(M3TQ.precompute(reader, value.length()));
            check(reader.reads == value.length(), "containment cold reads");
            reader.sealed = true;
            readers.add(reader);
            TreeSet<Long> expected = new TreeSet<>();
            for (long key : oracle(value, 0, value.length())) expected.add(key);
            keys.add(expected);
        }
        for (int source = 0; source < facts.size(); source++) {
            for (int required = 0; required < facts.size(); required++) {
                boolean expected = keys.get(source).containsAll(keys.get(required));
                check(facts.get(source).containsAll(facts.get(required)) == expected,
                        "containment set oracle");
                containmentPairs++;
            }
            expect(NullPointerException.class, () -> facts.get(0).containsAll(null));
            check(readers.get(source).reads == values.get(source).length(),
                    "containment performs no warm payload reads");
        }
        var candidate = M3TQ.precompute("abc-bcd", 7);
        var required = M3TQ.precompute("abcd", 4);
        check(candidate.containsAll(required), "containment necessary condition");
        check(!"abc-bcd".contains("abcd"), "containment is not exact text matching");
        check(M3TQ.precompute("abcabc", 6).containsAll(M3TQ.precompute("abcabcabc", 9)),
                "set containment discards multiplicity");
        check(M3TQ.precompute("abcabc", 6).containsAll(M3TQ.precompute("bcabca", 6)),
                "set containment discards ordering");
        Fence leftReader = new Fence("ab", 0, 2), rightReader = new Fence("cd", 0, 2);
        var left = M3TQ.precompute(leftReader, 2);
        var right = M3TQ.precompute(rightReader, 2);
        leftReader.sealed = rightReader.sealed = true;
        var joined = left.concat(right, 4);
        check(joined.containsAll(required) && required.containsAll(joined),
                "seam facts retain containment without payload reads");
    }

    private static void queryAlgebra() {
        var a = M3TQ.fromExact(List.of("abc"));
        var b = M3TQ.fromExact(List.of("bcd"));
        var c = M3TQ.fromExact(List.of("def", "xyz"));
        for (int mask = 0; mask < 16; mask++) {
            final int selected = mask;
            java.util.function.LongPredicate membership = key -> {
                long[] keys = {M3TQ.trigram('a','b','c'), M3TQ.trigram('b','c','d'),
                        M3TQ.trigram('d','e','f'), M3TQ.trigram('x','y','z')};
                for (int i = 0; i < keys.length; i++) if (keys[i] == key) return (selected & (1 << i)) != 0;
                return false;
            };
            check(M3TQ.and(List.of(a,b,c)).test(membership) ==
                    ((mask & 3) == 3 && (mask & 12) != 0), "AND/OR truth table");
            check(M3TQ.or(List.of(a,b)).test(membership) == ((mask & 3) != 0), "OR truth table");
            check(M3TQ.and(List.of(a,M3TQ.none())).test(membership) == false, "NONE absorber");
            check(M3TQ.or(List.of(b,M3TQ.all())).test(membership), "ALL absorber");
        }
        check(M3TQ.fromExact(List.of()).op() == M3TQ.Op.NONE, "empty language");
        check(!M3TQ.fromExact(List.of("abc", "x")).hasConstraints(), "short branch admits all");
        check(!M3TQ.and(List.of()).hasConstraints(), "empty AND");
        check(M3TQ.or(List.of()).op() == M3TQ.Op.NONE, "empty OR");
        check(M3TQ.and(List.of(a,a)).termCount() == 1, "unique flattened keys");
        check(M3TQ.or(List.of(M3TQ.none(),a)).termCount() == 1, "identity flattening");
        long[] export = a.trigrams(); export[0] = -1;
        check(a.trigrams()[0] == M3TQ.trigram('a','b','c'), "query defensive export");
        expect(UnsupportedOperationException.class, () -> a.subqueries().add(b));
        check(a.toString().contains("abc") && M3TQ.none().toString().equals("NONE"), "query rendering");
        var falsePositive = M3TQ.precompute("abc-bcd", 7);
        check(M3TQ.fromExact(List.of("abcd")).testPrecomputed(falsePositive), "deliberate guard positive");
        check(!Pattern.compile("abcd").matcher("abc-bcd").find(), "guard positive is not a match");
    }

    private static void refusals() {
        Fence unread = new Fence("abcd", 0, 4); unread.sealed = true;
        expect(NullPointerException.class, () -> M3TQ.precompute((CharSequence) null, 1));
        expect(IllegalArgumentException.class, () -> M3TQ.precompute(unread, -1));
        expect(IllegalArgumentException.class, () -> M3TQ.precompute(unread, 3));
        expect(IndexOutOfBoundsException.class, () -> M3TQ.precompute(unread, -1, 2, 4));
        expect(IndexOutOfBoundsException.class, () -> M3TQ.precompute(unread, 3, 2, 4));
        expect(IndexOutOfBoundsException.class, () -> M3TQ.precompute(unread, 0, 5, 4));
        expect(IllegalArgumentException.class, () -> M3TQ.precompute(unread, 1, 4, 2));
        check(unread.reads == 0, "refusals precede payload reads");
        var a = M3TQ.precompute("abc", 3);
        expect(NullPointerException.class, () -> a.concat(null, 3));
        expect(IllegalArgumentException.class, () -> a.concat(a, 5));
        expect(IllegalArgumentException.class, () -> M3TQ.precompute("", 0).concat(a, -1));
        expect(NullPointerException.class, () -> M3TQ.all().testPrecomputed(null));
        expect(NullPointerException.class, () -> M3TQ.fromExact(null));
        expect(NullPointerException.class, () -> M3TQ.and(Arrays.asList(M3TQ.all(),null)));
        expect(NullPointerException.class, () -> M3TQ.precompute((M3StringBacking) null, 1, 0, 0, 0));
        expect(NullPointerException.class, () -> nativeKeys(null));
        expect(NullPointerException.class, () -> nativeRangeKeys(null, 0, 0, 0));
        expect(IndexOutOfBoundsException.class, () -> nativeRangeKeys(new char[1], -1, 1, 1));
        expect(IndexOutOfBoundsException.class, () -> nativeRangeKeys(new char[1], 1, 0, 1));
        expect(IndexOutOfBoundsException.class, () -> nativeRangeKeys(new char[1], 0, 2, 1));
        expect(IllegalArgumentException.class, () -> nativeRangeKeys(new char[1], 0, 1, 0));
        expect(IllegalArgumentException.class, () -> nativeRangeKeys(new char[0], 0, 0, -1));
        equal(new long[0], nativeRangeKeys(new char[0], 0, 0, 0), "native empty");
        nativeCalls += 8;
    }

    private static void mapped() throws Exception {
        var writer = M3MappedStringBackingTest.class.getDeclaredMethod("writeFixture", Path.class, String.class);
        writer.setAccessible(true);
        Path directory = Files.createTempDirectory("m3-tq");
        int file = 0;
        for (String text : List.of("", "a", "ab", "abc", "ababa", "A\uD800x\uD83D\uDE00\uDC00Z", "\u0000\u00FF\u0100")) {
            Path path = directory.resolve("text-" + file++ + ".midx");
            writer.invoke(null, path, text);
            try (var owner = M3MappedStringBacking.open(path)) {
                for (long id : new long[]{1, (7L << 32) | 2}) {
                    for (int from = 0; from <= text.length(); from++) {
                        for (int to = from; to <= text.length(); to++) {
                            var reader = new BackingFence(owner, id, from, to);
                            int length = to - from;
                            var facts = M3TQ.precompute(reader, id, from, to, length);
                            check(reader.reads == length, "mapped single scan");
                            int split = from + length / 2;
                            var left = M3TQ.precompute(reader, id, from, split, length);
                            var right = M3TQ.precompute(reader, id, split, to, length);
                            reader.sealed = true;
                            equal(oracle(text, from, to), facts.keys(), "mapped facts");
                            equal(facts.keys(), left.concat(right, length).keys(), "mapped zero-read reuse");
                            expect(IllegalArgumentException.class, () -> M3TQ.precompute(reader, id, reader.from, reader.to, -1));
                            mappedRanges++;
                        }
                    }
                }
            }
        }
    }

    private static long[] oracle(String value, int from, int to) {
        TreeSet<Long> keys = new TreeSet<>();
        for (int i = from; i + 2 < to; i++) {
            keys.add(value.charAt(i) * 4294967296L + value.charAt(i+1) * 65536L + value.charAt(i+2));
        }
        return keys.stream().mapToLong(Long::longValue).toArray();
    }

    private static final class Fence implements CharSequence {
        final String value; final int from, to; int reads; boolean sealed;
        Fence(String value, int from, int to) { this.value=value; this.from=from; this.to=to; }
        public int length() { return value.length(); }
        public char charAt(int index) {
            check(!sealed && index >= from && index < to, "payload read outside admitted cold scan");
            reads++; return value.charAt(index);
        }
        public CharSequence subSequence(int start, int end) { throw new AssertionError("no slicing"); }
        public String toString() { throw new AssertionError("no materialization"); }
    }

    private static final class BackingFence implements M3StringBacking {
        final M3StringBacking delegate; final long id; final int from,to;
        int reads; boolean sealed;
        BackingFence(M3StringBacking delegate, long id, int from, int to) {
            this.delegate=delegate; this.id=id; this.from=from; this.to=to;
        }
        public int length(long key) { check(key==id,"owner id"); return delegate.length(key); }
        public char charAt(long key, int index) {
            check(key==id && !sealed && index>=from && index<to,"backing payload fence");
            reads++; return delegate.charAt(key,index);
        }
        public void close() { throw new AssertionError("precompute cannot close owner"); }
        public int utf8Length(long key) { throw new AssertionError("no encoding"); }
        public int codePointCount(long key) { throw new AssertionError("exact code units"); }
        public int unpairedSurrogateCount(long key) { throw new AssertionError("no source facts assumed"); }
        public int hashCode(long key) { throw new AssertionError("no hash identity"); }
        public CharBuffer utf16View(long key) { throw new AssertionError("no view export"); }
        public ByteBuffer utf8View(long key) { throw new AssertionError("no encoding"); }
        public String materialize(long key) { throw new AssertionError("no payload copy"); }
    }

    private static void equal(long[] expected, long[] actual, String label) {
        check(Arrays.equals(expected, actual), label);
    }
    private static void expect(Class<? extends Throwable> type, Runnable operation) {
        try { operation.run(); } catch (Throwable failure) {
            if (type.isInstance(failure)) { checks++; return; }
            throw new AssertionError("expected " + type.getName(), failure);
        }
        throw new AssertionError("missing " + type.getName());
    }
    private static void check(boolean condition, String label) {
        checks++;
        if (!condition) throw new AssertionError(label);
    }
}

